always-actions.script:
taskListReturn = appRoot === 'Commons' ? ec.service.sync().name('ironstone.commons.TaskServices.get#TaskListFind')
        .parameters({findJson: taskListFind || null}).call() : {findMap: {}, findJson: null}
taskListFind = taskListReturn.findJson || null

actions.script:
const detail = ec.service.sync().name('ironstone.projects.WorkItemServices.get#WorkItemDetail').parameters({workEffortId: workEffortId}).call() || {}
if (!ec.message.hasError() && detail.detail?.visible) {
    const task = detail.detail.task || {}
    const item = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
    const day = (value) => value == null || value === '' ? '' : ec.l10n.format(value, 'yyyy-MM-dd')
    const num = (value) => value == null || value === '' ? '' : String(Number(String(value)))
    const current = {title: item.workEffortName || '', type: item.purposeEnumId || '', priority: item.priority != null ? String(item.priority) : '',
        start: day(item.estimatedStartDate), due: day(item.estimatedCompletionDate), estimate: num(item.estimatedWorkTime), remaining: num(item.remainingWorkTime),
        points: num(item.estimatedPoints), budget: num(item.totalTimeAllowed), visibility: item.visibilityEnumId || '',
        milestone: detail.planItems?.milestone?.workEffortId || '', release: detail.planItems?.release?.workEffortId || '',
        component: detail.planItems?.component?.workEffortId || '', sprint: detail.planItems?.sprint?.workEffortId || '',
        parent: item.parentWorkEffortId || '', description: item.description || '', resolution: item.resolutionEnumId || ''}
    const posted = {title: workEffortName, type: purposeEnumId, priority: priority, start: estimatedStartDate, due: estimatedCompletionDate,
        estimate: estimatedWorkTime, remaining: remainingWorkTime, points: estimatedPoints, budget: totalTimeAllowed, visibility: visibilityEnumId,
        milestone: milestoneId, release: releaseId, component: componentId, sprint: sprintId, parent: parentWorkEffortId, description: description,
        resolution: resolutionEnumId}
    let changed = 0
    for (const field of Object.keys(posted)) {
        if (posted[field] === undefined || posted[field] === null) continue
        // an issue's text is its topic's first post (mr-pass design-smithy §8.1): never edited as the task's description
        if (field === 'description' && detail.issue) continue
        const value = String(posted[field]).trim()
        const before = field === 'due' || field === 'start' ? current[field] : field === 'estimate' || field === 'remaining' || field === 'points' || field === 'budget'
                ? current[field] : current[field]
        const same = ['estimate', 'remaining', 'points', 'budget'].includes(field) ? (value === '' ? before === '' : before !== '' && Number(value) === Number(before))
                : value === before
        if (same) continue
        ec.service.sync().name('ironstone.projects.WorkItemServices.update#WorkItemField').parameters({workEffortId: workEffortId, field: field === 'resolution' ? 'resolution' : field,
            value: value}).call()
        if (ec.message.hasError()) break
        changed++
    }
    if (!ec.message.hasError()) ec.message.addMessage(changed ? ec.l10n.localize('Work item saved') : ec.l10n.localize('Nothing changed'), 'success')
}

service-call.in-map:
{workEffortId:workEffortId, frequency:(frequency || null),
                    interval:(interval || 1), byDay:(byDay || null), byMonthDay:(byMonthDay || null), count:(count || null), until:(until || null),
                    fromCompletion:(fromCompletion || 'N')}

actions.script:
if (!ec.message.hasError()) {
    if (moveOut.failedCount) ec.message.addError(moveOut.failures[0].reason)
    else ec.message.addMessage(ec.resource.expand('${workEffortId} moved to ${project} with its sub-items', '', {workEffortId, project: rootWorkEffortId}), 'success')
}

service-call.in-map:
{parentWorkEffortId:(underId || workEffortId),
                    workEffortName:(workEffortName || ''), purposeEnumId:(purposeEnumId || null), assignToPartyId:(assignToPartyId || null),
                    estimatedWorkTime:(estimatedWorkTime || null)}

actions.script:
const level = ec.service.sync().name('mantle.work.ProjectServices.get#WorkItemTree').parameters({parentWorkEffortId: parentWorkEffortId || workEffortId}).call() || {}
const rows = Array.from(level.workItemList || [])
const decorated = rows.length ? (ec.service.sync().name('ironstone.projects.WorkItemServices.decorate#WorkItemRows').parameters({taskList: rows}).call()?.rowList || []) : []
ec.web.sendJsonResponse({subItemList: decorated.map((row) => Object.assign(row, {subItemId: row.workEffortId,
    parentWorkEffortId: row.parentWorkEffortId === workEffortId ? '' : row.parentWorkEffortId}))})

const access = ec.service.sync().name('ironstone.commons.TaskServices.get#TaskAccess').parameters({workEffortId: subItemId, need: 'update', app: 'projects'}).call()
let out = null
if (!ec.message.hasError()) out = ec.service.sync().name('mantle.work.TaskServices.move#Task').parameters({workEffortId: subItemId,
    parentWorkEffortId: parentWorkEffortId || workEffortId, previousSiblingId: previousSiblingId || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: ec.resource.expand('${id} moved', '', {id: subItemId})}]})

projects = appRoot === 'Projects'
workItemIssue = null
issuePostList = []
// a client contact (the PROJECT_CLIENT permission; impl-projects.md P10b): the item's overview, its shared sub-items and its
// messages, no internal tab (links, code, time, files) and no control it would be refused
clientView = !!ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')
appKey = projects ? 'projects' : 'commons'
compact = peek === 'true'
detailPath = projects ? '/qapps/Projects/WorkItems/WorkItemDetail' : '/qapps/Commons/Tasks/TaskDetail'
// Manufacturing (impl-manufacturing P11): a follow-up task of a maintenance request of the user's plants
mfgTask = appRoot === 'Manufacturing'
productionTask = {}
if (mfgTask) detailPath = '/qapps/Manufacturing/WorkCenters/WorkItemDetail'
// Maintenance (impl-maintenance P7): a follow-up task of a work order the user reads; a work order or a process step is no task
mntTask = appRoot === 'Maintenance'
maintenanceTask = {}
if (mntTask) detailPath = '/qapps/Maintenance/WorkOrders/WorkItemDetail'
// Customer Service (impl-customer-service P2, crosscut §3.12, F49): a work item of a case the user sees, on the
// Commons rule (its transitions' 'commons' key), with the way back to its case
csTask = appRoot === 'CustomerService'
csCaseId = null
if (csTask) {
    detailPath = '/qapps/CustomerService/Cases/WorkItemDetail'
    ec.message.pushErrors()
    try {
        for (const link of ec.entity.find('mantle.request.RequestWorkEffort').condition('workEffortId', workEffortId).disableAuthz().list()) {
            const checked = ec.service.sync().name('ironstone.customerservice.AccessServices.check#Record')
                    .parameters({appRoot: appRoot, recordType: 'case', recordId: link.requestId}).call()
            if (!ec.message.hasError() && checked?.recordId) { csCaseId = link.requestId; break }
            ec.message.clearErrors()
        }
    } catch (error) {
        csCaseId = null
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
// People (impl-people P7): a checklist or equipment return task People admits, on the Commons rule, with its People context
pplTask = appRoot === 'People'
pplContext = null
if (pplTask) {
    detailPath = '/qapps/People/Tasks/WorkItemDetail'
    ec.message.pushErrors()
    try {
        pplContext = ec.service.sync().name('mantle.humanres.PeopleServices.get#ChecklistTask').parameters({workEffortId: workEffortId}).call() || null
        if (ec.message.hasError()) pplContext = null
    } catch (error) {
        pplContext = null
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
// Sales (impl-sales P4, crosscut §3.12 Sales row): an activity of a deal the user sees, on the Commons rule (Overview, Files
// and Chatter; no sub-task, time, clone or request), with the way back to its deal; completing it neither qualifies nor closes it
salTask = appRoot === 'Sales'
salesTask = {}
if (salTask) detailPath = '/qapps/Sales/Pipeline/WorkItemDetail'
// the Development tab: when the item's project has the Code module on or a repository linked (design §5)
devShown = false
if (projects) {
    const devItem = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
    if (devItem?.rootWorkEffortId) {
        const devModules = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: devItem.rootWorkEffortId}).call()?.settings?.WstModules
        devShown = String(devModules || '').split(',').map((key) => key.trim()).includes('code') || ec.entity.find('mantle.work.effort.WorkEffortGitRepository')
                .condition('workEffortId', devItem.rootWorkEffortId).conditionDate('fromDate', 'thruDate', null).count() > 0
    }
}
if (clientView) devShown = false
const tabKeys = clientView ? ['overview', 'subitems', 'chatter']
        : projects ? ['overview', 'subitems', 'links'].concat(devShown ? ['development'] : []).concat(['time', 'files', 'chatter'])
        : (pplTask || salTask) ? ['overview', 'files', 'chatter']
        : ['overview', 'subtasks', 'time', 'files', 'chatter']
tab = tabKeys.includes(tab) ? tab : 'overview'
let extra = {}
if (projects) {
    extra = ec.service.sync().name('ironstone.projects.WorkItemServices.get#WorkItemDetail').parameters({workEffortId: workEffortId}).call() || {}
    detail = extra.detail || {}
    // a task that is an issue of a repository (Smithy): its number, its public page and its outward conversation
    workItemIssue = extra.issue || null
    issuePostList = Array.from(workItemIssue?.postList || [])
} else {
    detail = ec.service.sync().name('ironstone.commons.TaskServices.get#TaskDetail').parameters({workEffortId: workEffortId}).call() || {}
}
recordFound = !!detail.visible && (!csTask || !!csCaseId) && (!pplTask || !!pplContext?.workEffortId)
// People: an HR reader of the employment who is none of the task's people reads its People context alone
pplReadOnly = pplTask && !recordFound && !!pplContext?.workEffortId
if (mntTask) {
    ec.message.pushErrors()
    try {
        maintenanceTask = ec.service.sync().name('ironstone.maintenance.WorkItemServices.get#WorkItemContext')
                .parameters({workEffortId: workEffortId}).call() || {}
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    recordFound = recordFound && !!maintenanceTask.available
}
if (salTask) {
    ec.message.pushErrors()
    try {
        salesTask = ec.service.sync().name('ironstone.sales.ContextServices.get#WorkItemContext')
                .parameters({workEffortId: workEffortId}).call() || {}
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    recordFound = recordFound && !!salesTask.available
}
if (mfgTask && recordFound) {
    ec.message.pushErrors()
    try {
        productionTask = ec.service.sync().name('ironstone.manufacturing.DowntimeServices.get#WorkItemContext')
                .parameters({workEffortId: workEffortId}).call() || {}
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    recordFound = !!productionTask.available
}
if (!recordFound) return
const L = (text) => ec.l10n.localize(text)
const enc = (text) => String(text == null ? '' : text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;')
task = detail.task
canUpdate = !!detail.canUpdate
canDelete = !!detail.canDelete
parentTaskId = workEffortId
// the status-bar: the stages and the statuses the user may move the task to
statusFlowId = detail.statusFlowId || 'Default'
stageStatusIds = detail.stageStatusIds || []
allowedStatusIds = detail.allowedStatusIds || []
subTaskList = detail.subTaskList || []
timeEntryList = detail.timeEntryList || []
openTimeEntry = detail.openTimeEntry
otherOpenTimeEntry = detail.otherOpenTimeEntry
linkedRecordList = detail.linkedRecordList || []
partyList = detail.partyList || []
myHoursText = detail.myHoursText
// in Projects the Time tab also shows the time of everyone on the item (impl-projects.md P6b)
itemTime = null
if (projects && tab == 'time') {
    ec.message.pushErrors()
    try { itemTime = ec.service.sync().name('ironstone.projects.TimeServices.get#ItemTime').parameters({workEffortId: workEffortId}).call()?.itemTime || null }
    finally { ec.message.clearErrors(); ec.message.popErrors() }
}
itemTimeRows = Array.from(itemTime?.rowList || [])
itemTimeShown = !!itemTime
captionText = [L('Task') + ' ' + workEffortId, task.purposeLabel, task.projectName ? L('Project') + ': ' + task.projectName : null].filter((part) => part).join(' · ')
// the key facts: due, priority, assignees (and in Projects the estimate, plan items and labels)
const fact = (label, value, cls) => '<div class="col-auto"><div class="text-caption m-muted">' + enc(L(label)) + '</div><div class="text-body2' + (cls ? ' ' + cls : '') + '">' + value + '</div></div>'
const assignees = (task.assigneeList || []).map((party) => '<span class="row inline items-center no-wrap q-mr-sm"><m-avatar name="' + enc(party.name) + '"' + (party.userId ? ' user-id="' + enc(party.userId) + '"' : '') + ' size="22px" class="q-mr-xs"></m-avatar>'
        + enc(party.name) + '</span>').join('')
factsHtml = '<div class="row q-col-gutter-lg m-task-facts">'
    + (projects ? fact('Assignees', assignees || enc(L('Unassigned')), '') : '')
    + fact('Due', task.dueText ? enc(task.dueText) + (task.overdue ? ' · ' + enc(L('overdue')) : '') : enc(L('No due date')), task.overdue ? 'text-warning text-weight-medium' : '')
    + fact('Priority', task.priorityText ? enc(task.priorityText) : '—', '')
    + (!projects ? fact('Assignees', assignees || enc(L('Nobody')), '') : '')
    + (task.onToday ? fact('Today', '<q-icon name="sym_o_today" size="xs" class="q-mr-xs"></q-icon>' + enc(L('On your Today')), 'text-primary') : '')
    + (task.isWatcher && !projects ? fact('Following', enc(L('You watch this task')), '') : '')
if (projects) {
    const rollup = extra.rollup || {}
    const plans = extra.planItems || {}
    planItems = plans
    rollupInfo = rollup
    factsHtml += fact('Estimate', rollup.estimatedText ? enc(rollup.estimatedText) + ' h' : '—', '')
    if (rollup.childCount) factsHtml += fact('With sub-items', enc(rollup.totalEstimatedText || '0') + ' h · ' + enc(String(rollup.doneCount)) + '/' + enc(String(rollup.itemCount)) + ' ' + enc(L('done')), '')
    if (rollup.pointsText) factsHtml += fact('Points', enc(rollup.pointsText), '')
    if (plans.sprint) {
        const sprintUrl = '/qapps/Projects/WorkItems/SprintDetail?workEffortId=' + encodeURIComponent(plans.sprint.workEffortId)
        factsHtml += fact('Sprint', '<a href="' + enc(sprintUrl) + '" @click.prevent="$root.setUrl(\'' + enc(sprintUrl) + '\')">' + enc(plans.sprint.name) + '</a>', '')
    }
    for (const [key, label] of [['milestone', 'Milestone'], ['release', 'Release']])
        if (plans[key]) factsHtml += fact(label, enc(plans[key].name), '')
    const labels = extra.labelList || []
    if (labels.length) factsHtml += fact('Labels', labels.map((label) => '<q-chip dense square class="q-ma-none q-mr-xs m-tonal text-' + enc(label.colorName) + '">' + enc(label.label) + '</q-chip>').join(''), '')
}
factsHtml += '</div>'
// the tabs: Chatter is a tab only below 1440 px, beside the overview from there
const tabs = clientView ? [['overview', 'Overview'], ['subitems', 'Sub-items'], ['chatter', 'Messages']] : projects ? [['overview', 'Overview'], ['subitems', 'Sub-items' + ((extra.rollup?.childCount) ? ' (' + extra.rollup.childCount + ')' : '')],
        ['links', 'Links' + ((extra.relationList || []).length ? ' (' + extra.relationList.length + ')' : '')]].concat(devShown ? [['development', 'Development']] : [])
        .concat([['time', 'Time'], ['files', 'Files'], ['chatter', 'Chatter']])
    : (pplTask || salTask) ? [['overview', 'Overview'], ['files', 'Files'], ['chatter', 'Chatter']]
    : [['overview', 'Overview'], ['subtasks', 'Sub-tasks' + (subTaskList.length ? ' (' + subTaskList.length + ')' : '')], ['time', 'Time'], ['files', 'Files'], ['chatter', 'Chatter']]
const base = detailPath + '?workEffortId=' + encodeURIComponent(workEffortId)
        + (taskListFind ? '&taskListFind=' + encodeURIComponent(taskListFind) : '')
tabsHtml = '<q-tabs dense no-caps inline-label narrow-indicator outside-arrows mobile-arrows align="left" active-color="primary" indicator-color="primary"'
        + ' class="text-grey-8 m-task-tabs" model-value="' + enc(tab) + '">' + tabs.map(([key, label]) => {
            const cls = key === 'chatter' && tab !== 'chatter' ? ' class="lt-lg"' : ''
            return '<q-tab name="' + key + '" label="' + enc(L(label)) + '"' + cls + ' data-tab="' + key + '" @click="$root.setUrl(\'' + enc(base + '&tab=' + key) + '\')"></q-tab>'
        }).join('') + '</q-tabs><q-separator class="q-mb-sm"></q-separator>'
// the tabs in the terminal: links to this screen with the tab
tabsTui = {t: 'row', id: 'TaskTabs', c: tabs.map(([key, label]) => ({t: 'link', id: 'TaskTab_' + key, text: key === tab ? '[' + L(label) + ']' : L(label),
    url: sri.buildUrl('.').path + base.substring(base.indexOf('?')) + '&tab=' + key}))}
linkedRecordsHtml = linkedRecordList.map((record) => '<m-record-card record-entity="' + enc(record.recordEntityName) + '" record-id="' + enc(record.recordId)
        + '" card-url="/apps/Commons/Chatter/recordCard" class="q-mb-xs"></m-record-card>').join('')
todayText = ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
dueEditText = task.dueEditText || ''
projectLabel = task.projectName || ''

if (projects) {
    const item = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
    const day = (value) => value == null || value === '' ? '' : ec.l10n.format(value, 'yyyy-MM-dd')
    const num = (value) => value == null || value === '' ? '' : String(Number(String(value)))
    const enumText = (id) => id ? (ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one()?.description || id) : ''
    canManage = !!detail.canManage
    typeIcon = extra.typeIcon || 'sym_o_task_alt'
    breadcrumbList = extra.breadcrumbList || []
    breadcrumbHtml = '<div class="row items-center q-gutter-x-xs text-caption m-workitem-path">' + breadcrumbList.map((crumb, i) =>
            (i ? '<q-icon name="sym_o_chevron_right" size="xs" class="m-muted"></q-icon>' : '') + '<a href="' + enc(crumb.url) + '" @click.prevent="$root.setUrl(\'' + enc(crumb.url) + '\')">'
            + enc(crumb.label) + '</a>').join('') + '</div>'
    labelList = extra.labelList || []
    relationList = extra.relationList || []
    requestList = extra.requestList || []
    subItemList = (extra.subItemList || []).map((row) => Object.assign({}, row, {subItemId: row.workEffortId,
        parentWorkEffortId: row.parentWorkEffortId === workEffortId ? '' : row.parentWorkEffortId}))
    subItemTotals = extra.subItemTotals || {}
    recurrence = extra.recurrence || null
    isWatcher = !!task.isWatcher
    isFollower = ec.entity.find('mantle.party.communication.RecordFollower').condition('recordEntityName', 'mantle.work.effort.WorkEffort')
            .condition('recordId', workEffortId).condition('userId', ec.user.userId).count() > 0
    isDoneItem = ['WeComplete', 'WeClosed', 'WeCancelled'].includes(item.statusId)
    // the Details and the values of the Edit dialog
    fields = {workEffortName: item.workEffortName || '', purposeEnumId: item.purposeEnumId || '', priority: item.priority != null ? String(item.priority) : '5',
        estimatedStartDate: day(item.estimatedStartDate), estimatedCompletionDate: day(item.estimatedCompletionDate),
        estimatedWorkTime: num(item.estimatedWorkTime), remainingWorkTime: num(item.remainingWorkTime), estimatedPoints: num(item.estimatedPoints),
        totalTimeAllowed: num(item.totalTimeAllowed), visibilityEnumId: item.visibilityEnumId || '', resolutionEnumId: item.resolutionEnumId || '',
        milestoneId: planItems.milestone?.workEffortId || '', releaseId: planItems.release?.workEffortId || '', componentId: planItems.component?.workEffortId || '',
        sprintId: planItems.sprint?.workEffortId || '',
        parentWorkEffortId: item.parentWorkEffortId || '', description: item.description || ''}
    isTopLevel = !item.parentWorkEffortId
    detailsList = [['Type', task.purposeLabel], ['Status', task.statusLabel], ['Resolution', isDoneItem ? enumText(item.resolutionEnumId) : ''],
        ['Priority', task.priorityText], ['Project', task.projectName], ['Parent', item.parentWorkEffortId ? item.parentWorkEffortId + ' ' + (task.parentName || '') : ''],
        ['Milestone', planItems.milestone?.name], ['Release', planItems.release?.name], ['Sprint', planItems.sprint?.name], ['Component', planItems.component?.name],
        ['Starts', fields.estimatedStartDate], ['Due', fields.estimatedCompletionDate],
        ['Estimate', rollupInfo.estimatedText ? rollupInfo.estimatedText + ' h' + (rollupInfo.childCount ? ' (' + (rollupInfo.totalEstimatedText || '0') + ' h ' + L('with sub-items') + ')' : '') : ''],
        ['Remaining', rollupInfo.remainingText ? rollupInfo.remainingText + ' h' + (rollupInfo.childCount ? ' (' + (rollupInfo.totalRemainingText || '0') + ' h ' + L('with sub-items') + ')' : '') : ''],
        ['Actual', rollupInfo.actualText ? rollupInfo.actualText + ' h' + (rollupInfo.childCount ? ' (' + (rollupInfo.totalActualText || '0') + ' h ' + L('with sub-items') + ')' : '') : ''],
        ['% complete', rollupInfo.percentDone != null ? rollupInfo.percentDone + '%' : ''], ['Points', rollupInfo.pointsText],
        ['Hours budget', isTopLevel && rollupInfo.budgetText ? rollupInfo.budgetText + ' h' : ''], ['Visibility', enumText(item.visibilityEnumId)],
        ['Repeats', recurrence ? recurrence.text : '']]
            .filter((entry) => entry[1] != null && entry[1] !== '').map(([label, value]) => ({label: L(label), value: String(value)}))
    // the drop-downs of the Edit dialog
    const options = (service, parameters) => ec.service.sync().name(service).parameters(parameters).call()?.optionList || []
    milestoneOptions = options('ironstone.projects.WorkItemServices.get#PlanItemOptions', {rootWorkEffortId: item.rootWorkEffortId, workEffortTypeEnumId: 'WetMilestone'})
    releaseOptions = options('ironstone.projects.WorkItemServices.get#PlanItemOptions', {rootWorkEffortId: item.rootWorkEffortId, workEffortTypeEnumId: 'WetRelease'})
    componentOptions = options('ironstone.projects.WorkItemServices.get#PlanItemOptions', {rootWorkEffortId: item.rootWorkEffortId, workEffortTypeEnumId: 'WetComponent'})
    // the open sprints, and the item's own when it is complete (so an edit keeps it)
    sprintOptions = options('ironstone.projects.PlanningServices.get#SprintOptions', {rootWorkEffortId: item.rootWorkEffortId})
    if (planItems.sprint && !sprintOptions.some((option) => option.key === planItems.sprint.workEffortId))
        sprintOptions.push({key: planItems.sprint.workEffortId, text: planItems.sprint.name})
    labelOptions = options('ironstone.projects.WorkItemServices.get#LabelOptions', {}).filter((option) => !labelList.some((label) => label.labelId === option.key))
    projectOptions = ec.service.sync().name('ironstone.projects.WorkItemServices.get#ProjectOptions').parameters({memberOnly: true}).call()?.projectList || []
    parentText = item.parentWorkEffortId ? item.parentWorkEffortId + ' ' + (task.parentName || '') : ''
    keyChipHtml = '<q-chip dense square class="q-ma-none q-mr-sm text-mono m-workitem-key">' + enc(workEffortId) + '</q-chip>'
    repeatParts = {}
    if (recurrence?.rrule) for (const part of String(recurrence.rrule).split(';')) { const [k, v] = part.split('='); repeatParts[k] = v }
    // the Development tab's records, read only when it is open
    development = {hosting: false, branchList: [], mergeRequestList: [], commitList: [], tagList: [], pushRepositoryOptions: [], repositoryList: []}
    if (tab === 'development') {
        development = ec.service.sync().name('ironstone.projects.CodeServices.get#WorkItemDevelopment').parameters({workEffortId: workEffortId}).call()?.development || development
        ec.message.clearErrors()
        devRepositoryId = development.pushRepositoryOptions?.length === 1 ? development.pushRepositoryOptions[0].key : ''
        devBranchList = development.branchList || []; devMergeRequestList = development.mergeRequestList || []
        devCommitList = development.commitList || []; devTagList = development.tagList || []; devRepositoryOptions = development.pushRepositoryOptions || []
        devCheckout = development.branchName ? 'git fetch origin\ngit checkout ' + development.branchName : ''
    }
}
